      "rank": 1,
      "ballot_id": "B030",
      "proposed_laureates": ["Hidetoshi Katori", "Jun Ye"],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have transformed precision timekeeping and opened tests of fundamental physics and applications in geodesy.",
        "attribution": "Katori's lattice proposal and realization and Ye's major advances in clock performance form a strong, complementary case.",
        "maturity": "The technique is experimentally established, with repeated improvements and a clear path to practical use.",
        "uncertainties": ["How to distinguish the foundational invention from the broader international development of optical clocks."]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B014",
      "proposed_laureates": ["Carlton M. Caves", "H. Jeff Kimble", "Roman Schnabel"],
      "assessment": {
        "nobel_worthiness": "Squeezed light enables measurements beyond the conventional shot-noise limit and has become important to gravitational-wave detection.",
        "attribution": "Caves established the quantum limits and theoretical framework; Kimble helped define experimental quantum optics and interferometric applications; Schnabel represents the route to mature, high-performance squeezed-light sources.",
        "maturity": "Demonstrated in precision interferometry and increasingly consequential in operating detectors.",
        "uncertainties": ["The balance between foundational theory, early demonstrations, and later detector implementation makes the prize boundaries difficult."]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B003",
      "proposed_laureates": ["Federico Capasso", "Jérôme Faist", "Alfred Y. Cho"],
      "assessment": {
        "nobel_worthiness": "The quantum cascade laser created a versatile source across important mid- and far-infrared bands, with substantial scientific and technological impact.",
        "attribution": "Capasso and Faist are central to the device concept and its realization; Cho's epitaxial semiconductor expertise was crucial to making the structure possible.",
        "maturity": "The laser is a mature technology with decades of experimental validation and broad use.",
        "uncertainties": ["The division of credit between the original concept, semiconductor growth, and subsequent device engineering needs careful historical assessment."]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B034",
      "proposed_laureates": ["Christian J. Bordé", "Mark A. Kasevich", "David E. Pritchard"],
      "assessment": {
        "nobel_worthiness": "Atom interferometry turned coherent matter waves into a sensitive and broadly useful tool for inertial and fundamental-constant measurements.",
        "attribution": "Bordé's foundational atom-optics work and the complementary experimental contributions of Kasevich and Pritchard support a strong case.",
        "maturity": "The method is well established in laboratories and has advanced toward field applications, though performance depends strongly on implementation.",
        "uncertainties": ["The field has many important contributors, and credit across distinct interferometer designs may be difficult to delimit."]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B016",
      "proposed_laureates": ["Stephen E. Harris", "Lene Vestergaard Hau", "Atac Imamoglu"],
      "assessment": {
        "nobel_worthiness": "Electromagnetically induced transparency and coherent control of light revealed how atomic coherence can reshape propagation and enable quantum optical interfaces.",
        "attribution": "Harris's foundational EIT work and the landmark demonstrations by Hau and Imamoglu represent both the core phenomenon and its experimental reach.",
        "maturity": "The effects are repeatedly demonstrated and underpin later work in slow light and quantum memories.",
        "uncertainties": ["The nominated contributions span related but distinct advances in EIT, slow light, and coherent interfaces."]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B002",
      "proposed_laureates": ["Eli Yablonovitch", "Sajeev John", "Philip St.J. Russell"],
      "assessment": {
        "nobel_worthiness": "Photonic band-gap control established a powerful way to shape the propagation and confinement of light, influencing nanophotonics and optical communications.",
        "attribution": "Yablonovitch and John independently articulated key photonic-crystal concepts; Russell's photonic crystal fiber work demonstrated a major complementary realization.",
        "maturity": "The field has had decades to mature and produced useful devices and broad research directions.",
        "uncertainties": ["The discovery involved parallel theoretical and experimental work, and the connection between photonic crystals and photonic crystal fibers complicates a compact attribution."]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B050",
      "proposed_laureates": ["Alexandre Blais", "Robert J. Schoelkopf", "Steven M. Girvin"],
      "assessment": {
        "nobel_worthiness": "Circuit quantum electrodynamics made strong light–matter coupling accessible in engineered circuits and became a central platform for quantum information experiments.",
        "attribution": "Blais supplied key theoretical proposals, while Schoelkopf and Girvin were central to developing and interpreting the experimental platform.",
        "maturity": "The platform is experimentally robust and highly productive, though its long-term scientific and practical impact is still unfolding.",
        "uncertainties": ["The distinction between foundational cQED work and the much broader development of superconducting quantum processors remains unsettled."]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B043",
      "proposed_laureates": ["Markus Aspelmeyer", "Tobias J. Kippenberg", "Kerry J. Vahala"],
      "assessment": {
        "nobel_worthiness": "Cavity optomechanics opened precise control of mechanical motion through light and created a productive interface between quantum optics and mesoscopic physics.",
        "attribution": "Vahala's early cavity work and the later foundational experimental and theoretical development by Kippenberg and Aspelmeyer support the proposed group.",
        "maturity": "There are strong demonstrations of cooling and control, but some of the most ambitious quantum and sensing applications remain in development.",
        "uncertainties": ["The field is broad and active, so the eventual defining result and appropriate award boundary are not yet clear."]
      }
    }
  ]
